-- The pair itself (ObjectMgr::GetPlayerInfo). Start position = where the warriors of the race start.
DELETE FROM `playercreateinfo` WHERE `class` = 3 AND `race` IN (1, 5);
INSERT INTO `playercreateinfo` (`race`, `class`, `map`, `zone`, `position_x`, `position_y`, `position_z`, `orientation`)
SELECT `race`, 3, `map`, `zone`, `position_x`, `position_y`, `position_z`, `orientation`
FROM `playercreateinfo` WHERE `class` = 1 AND `race` IN (1, 5);

-- Starting weapon skills. The class skill lines, Leather, Defense and the like have no race mask and
-- come by themselves; the level 1 spells (Auto Shot, Raptor Strike) come with the skill lines.
-- Guns for the human rest on the skillraceclassinfo_dbc row at the end of this file.
DELETE FROM `playercreateinfo_skills` WHERE `raceMask` IN (1, 16, 17) AND `classMask` = 4;
INSERT INTO `playercreateinfo_skills` (`raceMask`, `classMask`, `skill`, `rank`, `comment`) VALUES
(1, 4, 46, 0, 'Hunter - Guns (Human)'),
(16, 4, 45, 0, 'Hunter - Bows (Undead)'),
(17, 4, 43, 0, 'Hunter - Swords (Human, Undead)');

